export interface Document_Document {
  /** Document represents the canonical document resource in Document AI. It is an interchange format that provides insights into documents and allows for collaboration between users and Document AI to iterate and optimize for quality. */
  cloudAiDocument?: Document_CloudAiDocument | Computed<Document_CloudAiDocument>;
  /** Indicates the category (image, audio, video etc.) of the original content. */
  contentCategory?: string | Computed<string>;
  /** Output only. The time when the document is created. */
  createTime?: string | Computed<string>;
  /** The user who creates the document. */
  creator?: string | Computed<string>;
  /** Required. Display name of the document given by the user. This name will be displayed in the UI. Customer can populate this field with the name of the document. This differs from the 'title' field as 'title' is optional and stores the top heading in the document. */
  displayName?: string | Computed<string>;
  /** Uri to display the document, for example, in the UI. */
  displayUri?: string | Computed<string>;
  /** Output only. If linked to a Collection with RetentionPolicy, the date when the document becomes mutable. */
  dispositionTime?: string | Computed<string>;
  /** The Document schema name. Format: projects/{project_number}/locations/{location}/documentSchemas/{document_schema_id}. */
  documentSchemaName?: string | Computed<string>;
  /** Raw document content. */
  inlineRawDocument?: string | Computed<string>;
  /** Output only. Indicates if the document has a legal hold on it. */
  legalHold?: boolean | Computed<boolean>;
  /** The resource name of the document. Format: projects/{project_number}/locations/{location}/documents/{document_id}. The name is ignored when creating a document. */
  name?: string | Computed<string>;
  /** Other document format, such as PPTX, XLXS */
  plainText?: string | Computed<string>;
  /** List of values that are user supplied metadata. */
  properties?: Document_Document_Properties[] | Computed<Document_Document_Properties[]>;
  /** This is used when DocAI was not used to load the document and parsing/ extracting is needed for the inline_raw_document. For example, if inline_raw_document is the byte representation of a PDF file, then this should be set to: RAW_DOCUMENT_FILE_TYPE_PDF. */
  rawDocumentFileType?: string | Computed<string>;
  /** Raw document file in Cloud Storage path. */
  rawDocumentPath?: string | Computed<string>;
  /** The reference ID set by customers. Must be unique per project and location. */
  referenceId?: string | Computed<string>;
  /** If true, text extraction will not be performed. */
  textExtractionDisabled?: boolean | Computed<boolean>;
  /** If true, text extraction will be performed. */
  textExtractionEnabled?: boolean | Computed<boolean>;
  /** Title that describes the document. This can be the top heading or text that describes the document. */
  title?: string | Computed<string>;
  /** Output only. The time when the document is last updated. */
  updateTime?: string | Computed<string>;
  /** The user who lastly updates the document. */
  updater?: string | Computed<string>;
}

